#!/usr/bin/env bash
# Generated by Phase: IMPLEMENT | Feature: #143
# test-discovery-literals.sh — what SETUP discovery offers is what the rest of SETUP accepts (#143). META-ONLY.
# One check per fix class. Each reads the literals the questions offer (`Factory-setup-discovery`: a question's
# `**Options:**` and its one `**Persist:**` key) and fails where a consumer names a key no question persists or a
# literal no question offers: manifest conditionals, materialisation steps, the verification loop's rows, the
# DEVOPS enums and labels, the infrastructure-registry schema, the shipped scripts. The interim guard until the
# answer registry and its validator (#159) replace it.
#
# Usage: test-discovery-literals.sh [--root DIR]      exit 0 all green · 1 a check failed · 2 infra
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
[ "${1:-}" = "--root" ] && ROOT="$(cd "$2" && pwd)"
command -v python3 >/dev/null || { echo "test-discovery-literals: python3 required" >&2; exit 2; }
python3 - "$ROOT" <<'PY'
import fnmatch, json, re, subprocess, sys
from pathlib import Path

R = Path(sys.argv[1])
def read(rel):
    return (R / rel).read_text(encoding="utf-8")
try:
    DISC = read(".claude/instructions/Factory-setup-discovery.instructions.md")
    MANIFEST = json.loads(read(".context/templates/setup/governance_versions.json"))
except (OSError, ValueError) as e:
    print(f"test-discovery-literals: cannot read the discovery or the manifest ({e})", file=sys.stderr); sys.exit(2)

# ── the offered literals: one persisted key per question, its options ───────────────────────────────────────
OPTS, PERSISTED = {}, set()
for blk in re.split(r"\n(?=#{4,5} Q)", DISC):
    h = re.match(r"#{4,5} (Q[\d.]+[a-z]?)\b", blk)
    if not h:
        continue
    per = re.search(r"^- \*\*Persist[^*]*:\*\*\s*(.+)$", blk, re.M)
    toks = re.findall(r"`([^`]+)`", per.group(1)) if per else []
    keys = [t.rstrip("[]") for t in toks if re.fullmatch(r"[a-z_]+(?:\.[a-z_]+)+(?:\[\])?", t)]
    PERSISTED.update(keys)
    opt = re.search(r"^- \*\*Options[^*]*:\*\*\s*(.+)$", blk, re.M)
    rows = [opt.group(1)] if opt else re.findall(r"^- [^*`\n]+ → (.+)$", blk, re.M)  # Q10: per-framework rows
    opts = [re.sub(r"\s*\(.*$", "", o).strip().strip("`") for row in rows for o in row.split("|")]
    if not opts or any(not o or len(o) > 30 or re.search(r"[`:*]|^-", o) for o in opts):
        continue  # options written as prose or bullets: not a literal list
    OPTS[h.group(1)] = sorted(set(opts))
    if len(keys) == 1 or (keys and len(keys) == len(toks)):  # values named beside the key are a mapping, not literals
        OPTS[keys[0]] = OPTS[h.group(1)]

FAILS = 0
def check(label, findings):
    global FAILS
    if findings:
        FAILS += 1
        print(f"  ✗ {label}")
        for f in findings[:12]:
            print(f"      {f}")
    else:
        print(f"  ✓ {label}")

def tracked(*roots):
    r = subprocess.run(["git", "-C", str(R), "ls-files", "--", *roots], capture_output=True, text=True)
    if r.returncode or not r.stdout.split():  # a check over no files is no check
        print(f"  ✗ git ls-files {' '.join(roots)} listed nothing ({r.stderr.strip()[:120]})")
        sys.exit(1)
    return [f for f in r.stdout.split() if "CHANGELOG" not in f and not f.endswith("governance_versions.json")]

# ── 1 · conditional keys and literals ───────────────────────────────────────────────────────────────────────
CLAUSE = re.compile(r"^\s*([A-Za-z_][\w.]*)\s*(?:(==|!=)\s*(.+?)|(exists))\s*$")
def manifest_entries():
    for sect, entries in MANIFEST.items():
        if isinstance(entries, dict):
            for k, e in entries.items():
                if isinstance(e, dict):
                    yield sect, k, e
found = []
for sect, k, e in manifest_entries():
    c = e.get("stack_conditional")
    if not isinstance(c, str):
        continue
    for clause in re.split(r"\s+(?:OR|AND)\s+", c):
        m = CLAUSE.match(clause)
        if not m:
            found.append(f"manifest {k}: `{clause}` — not a `key == value` / `key != value` / `key exists` clause"); continue
        key, op, val = m.group(1), m.group(2), (m.group(3) or "").strip().strip('"')
        if m.group(4):
            if not any(p == key or p.startswith(key + ".") for p in PERSISTED):
                found.append(f"manifest {k}: `{key} exists` — no question persists `{key}` or a key under it")
        elif key not in PERSISTED:
            found.append(f"manifest {k}: `{key}` — no question persists this key")
        elif key in OPTS and val not in OPTS[key] + ["None", "null"]:
            found.append(f"manifest {k}: `{key} {op} {val}` — `{val}` is not offered ({' | '.join(OPTS[key])})")
CMP = re.compile(r"`?\b(Q\d+(?:\.\d+)?[a-z]?|[a-z_]+(?:\.[a-z_]+)+)`?\s*(==|!=)\s*"
                 r"(?:\"([^\"]+)\"|`([^`]+)`|'([^']+)'|((?!(?:AND|OR)\b)[\w.#+/-]+))")
for rel in tracked(".claude", ".context/templates"):
    try:
        text = read(rel)
    except (UnicodeDecodeError, OSError):
        continue
    for n, line in enumerate(text.splitlines(), 1):
        for m in CMP.finditer(line):
            key, val = m.group(1), next(g for g in m.groups()[2:] if g is not None)
            if key in OPTS and val not in OPTS[key] + ["None", "null"]:
                found.append(f"{rel}:{n}: `{key} {m.group(2)} {val}` — `{val}` is not offered ({' | '.join(OPTS[key])})")
setup_fm = read(".context/templates/setup/setup/setup_master_template.md").split("\n---", 1)[0]
if not re.search(r"^project_mode: Greenfield \| Brownfield$", setup_fm, re.M):
    found.append("setup template frontmatter: Q3 persists `project_mode: Greenfield | Brownfield`, the template does not carry it")
check("conditional keys and literals: every key read is persisted, every literal compared is offered", found)

# ── 2 · CI slugs: the materialisation's platform table names Q21's literals ─────────────────────────────────
mat = read(".claude/instructions/Factory-setup-materialization.instructions.md")
rows = re.findall(r"^\| `([^`]+)` \| `(?:governance-check|inventory-drift)\.", mat, re.M)
q21 = OPTS.get("ci_cd.platform", [])
check("CI platform table: every row names a Q21 literal",
      [f"materialisation: `{r}` — not a Q21 literal ({' | '.join(q21)})" for r in rows if r not in q21] or
      ([] if rows else ["materialisation: no governance-check platform table found"]))

# ── 3 · a platform-specific workflow carries its platform's conditional ─────────────────────────────────────
by_slug, found = {}, []
for sect, k, e in manifest_entries():
    m = re.fullmatch(r"workflows/[\w-]+\.([a-z-]+)\.(?:ya?ml|groovy)", k)
    if not m:
        continue
    lit = re.search(r'ci_cd\.platform == "([^"]+)"', e.get("stack_conditional") or "")
    if not lit:
        found.append(f"manifest {k}: a `{m.group(1)}` workflow with no `ci_cd.platform == \"…\"` conditional — it lands on every platform")
    else:
        by_slug.setdefault(m.group(1), set()).add(lit.group(1))
found += [f"workflows `*.{s}.*` gate on different platforms: {sorted(v)}" for s, v in by_slug.items() if len(v) > 1]
check("platform workflows: each carries one ci_cd.platform conditional, the same for its slug", found)

# ── 4 · every Q21 option has its pipeline templates ─────────────────────────────────────────────────────────
conds = [(k, e.get("stack_conditional") or "") for _, k, e in manifest_entries()]
found = [] if q21 else ["discovery: no Q21 options parsed (ci_cd.platform)"]
for lit in q21:
    if lit == "None":
        continue
    for kind in ("governance-check", "auto-tag"):
        if not any(k.startswith(f"workflows/{kind}.") and f'"{lit}"' in c for k, c in conds):
            found.append(f"Q21 offers `{lit}`; no `workflows/{kind}.*` template materialises for it")
check("Q21: every option has a governance-check and an auto-tag template", found)

# ── 5 · host enum: cloud_provider accepts every Q20 option ──────────────────────────────────────────────────
cicd = read(".context/templates/setup/rules/ci-cd.md")
m = re.search(r"cloud_provider: \{\{CLOUD_PROVIDER\}\}\s*#\s*(.+)$", cicd, re.M)
enum = [x.strip() for x in m.group(1).split("|")] if m else []
check("host enum: rules/ci-cd.md cloud_provider accepts every Q20 option",
      [f"Q20 offers `{o}`; cloud_provider accepts {enum}" for o in OPTS.get("hosting.provider", []) if o not in enum]
      or ([] if OPTS.get("hosting.provider") else ["discovery: no Q20 options parsed (hosting.provider)"]))

# ── 6 · schema: every resource type the phases use is in the registry schema ────────────────────────────────
schema = json.loads(read(".context/schemas/infrastructure_registry.schema.json"))
def enum_of(node):
    if isinstance(node, dict):
        if "type" in node and isinstance(node["type"], dict) and "enum" in node["type"]:
            return node["type"]["enum"]
        for v in node.values():
            r = enum_of(v)
            if r:
                return r
    return None
types = enum_of(schema) or []
used = set()
for rel in tracked(".claude/instructions", ".claude/skills"):
    used.update(re.findall(r"resource\.type == \"([a-z_-]+)\"", read(rel)))
check("schema: every `resource.type` the phases compare is in infrastructure_registry.schema.json",
      [f"`{t}` used, the schema enum is {types}" for t in sorted(used) if t not in types] or
      ([] if types else ["no resource type enum in the schema"]))

# ── 7 · DEVOPS topology labels as Q7 defines them ───────────────────────────────────────────────────────────
q7 = dict(re.findall(r"\b(B\d+) \(([^,)]+), \$", DISC))
dep = read(".claude/instructions/Factory-devops-provision-deploy.instructions.md")
blk = re.search(r"Per architecture topology[^\n]*\n((?:[ \t]+.*\n)+?)\s*\n", dep)
found, seen = [], []
if not blk:
    found.append("Factory-devops-provision-deploy: no `Per architecture topology` block")
else:
    for code, name in re.findall(r"\b(B\d+) ([^,:]+?)(?=,|:)", blk.group(1)):
        seen.append(code)
        if q7.get(code) != name.strip():
            found.append(f"DEVOPS labels `{code} {name.strip()}`; Q7 defines `{code} {q7.get(code)}`")
    found += [f"{c} ({q7[c]}) — no build rule" for c in q7 if c not in seen]
    found += [f"{c} — more than one build rule" for c in set(seen) if seen.count(c) > 1]
check("DEVOPS topology: one build rule per Q7 code, under Q7's name", found)

# ── 8 · lint-format discovers the rule files as they are named ──────────────────────────────────────────────
lf = read(".context/templates/setup/scripts/lint-format.sh")
pat = re.search(r"find \.claude/rules [^\n]*-name '([^']+)'", lf)
rules = [Path(e["target"]).name for _, _, e in manifest_entries() if str(e.get("target", "")).startswith(".claude/rules/")]
check("lint-format: its rule discovery matches the rule files the manifest lands",
      [] if pat and any(fnmatch.fnmatch(r, pat.group(1)) for r in rules) else
      [f"lint-format.sh searches `.claude/rules` for `{pat.group(1) if pat else '?'}`; the rules land as {sorted(rules)[:4]}…"])

# ── 9 · migration layouts the validator scans ───────────────────────────────────────────────────────────────
vm = read(".context/templates/setup/scripts/validate-migrations.sh")
check("validate-migrations: PHP files, Supabase and Drizzle layouts are scanned",
      [f"validate-migrations.sh does not scan {w}" for w in ('--include="*.php"', '"supabase/migrations"', '"drizzle/migrations"') if w not in vm])

# ── 10 · one definition per fact ────────────────────────────────────────────────────────────────────────────
found = []
if len(re.findall(r"Q27 != \"None\" → \[Q27\.1", DISC)) != 1:
    found.append(f"discovery: Q27's unlock list is written {len(re.findall(r'Q27 != .None. → .Q27.1', DISC))} times")
bo = read(".claude/instructions/Factory-backlog-operations.instructions.md")
ms = re.search(r"milestone_strategy: \"\{\{milestone_strategy\}\}\"\s*# Q27\.3: (.+)$", bo, re.M)
lits = sorted(x.strip() for x in ms.group(1).split("|")) if ms else []
if lits != OPTS.get("Q27.3"):
    found.append(f"backlog adapter milestone_strategy lists {lits}; Q27.3 offers {OPTS.get('Q27.3')}")
usp = read(".context/templates/setup/upgrade_safety_protocol.md")
algos = {a for a, p in (("MD5", r"\bMD5\b"), ("SHA-256", r"\bSHA-?256")) if re.search(p, usp, re.I)}
if len(algos) != 1:
    found.append(f"upgrade_safety_protocol.md names {sorted(algos) or 'no'} checksum algorithm(s) for one checksum")
check("one definition: Q27's unlock list, Q27.3's literals, the upgrade checksum algorithm", found)

# ── 11 · the verification loop's rows name offered literals ─────────────────────────────────────────────────
bvl = read(".claude/skills/factory-build-verification/SKILL.md")
found = []
for key in ("backend.runtime", "frontend.framework"):
    # a block = its first row's indent, then every deeper line (continuations: ELIF / ELSE) until a shallower one
    blocks = [m.group(1) for m in re.finditer(r"MATCH stack\." + re.escape(key) + r":\n(([ \t]+)(?:\"|DEFAULT).*\n(?:\2[ \t]*\S.*\n)*)", bvl)]
    if not blocks or not OPTS.get(key):
        found.append(f"BVL: no `MATCH stack.{key}` block, or no {key} options parsed — nothing compared")
    for blk in blocks:
        indent = re.match(r"[ \t]*", blk).group(0)  # the block's own rows; a nested MATCH is another key's
        for row in re.findall(r"^" + indent + r"(\"[^→]+?)\s*→", blk, re.M):
            found += [f"BVL `MATCH stack.{key}` row `{lit}` — not offered ({' | '.join(OPTS.get(key, []))})"
                      for lit in re.findall(r"\"([^\"]+)\"", row) if lit not in OPTS.get(key, [])]
check("verification loop: every BVL stack row names an offered literal", sorted(set(found)))

print(f"test-discovery-literals: {'FAIL' if FAILS else 'OK'} ({FAILS} check(s) red)")
sys.exit(1 if FAILS else 0)
PY
